12	// gatewayPrefix anchors every read-only gateway route. The gateway is
13	// dispatched on the raw request target before ServeMux path cleaning, since
14	// the mux would rewrite or redirect raw ".", ".." and empty segments and its
15	// PathValue results are already percent-decoded, which would lose the exact
16	// single-decoding semantics the gateway contract requires.
17	const gatewayPrefix = "/v1/gateway/"
18	
19	// directoryMediaType is the media type of directory documents both when
20	// they are stored (as ordinary octet-stream objects) and when the gateway
21	// serves one back.
22	const directoryMediaType = "application/vnd.cidvault.directory+json"
23	
24	// directoryVersion is the only directory format version this server
25	// understands.
26	const directoryVersion = 1
27	
28	// maxDirectoryEntries bounds the number of entries one directory object may
29	// carry.
30	const maxDirectoryEntries = 4096
31	
32	// maxGatewaySegments bounds the number of path segments resolved in one
33	// gateway request, excluding the root CID.
34	const maxGatewaySegments = 64
35	
36	// maxNameRunes bounds a single directory entry name in Unicode code points.
37	const maxNameRunes = 255
