39	// directoryEntryJSON is one strictly decoded directory entry. Pointer
40	// fields distinguish a missing key from a zero value.
41	type directoryEntryJSON struct {
42		Name *string `json:"name"`
43		Type *string `json:"type"`
44		CID  *string `json:"cid"`
45	}
