47	// directoryJSON is the strictly decoded directory document. Top level may
48	// carry exactly the version and entries keys.
49	type directoryJSON struct {
50		Version *json.RawMessage      `json:"version"`
51		Entries *[]directoryEntryJSON `json:"entries"`
52	}
53	
54	// directoryEntry is one validated directory listing entry.
55	type directoryEntry struct {
56		name string
57		typ  string
58		cid  string
59	}
60	
61	// gateway handles every route under /v1/gateway/, including ones ServeMux
62	// would otherwise rewrite (raw dot-segments or empty segments), so it must
63	// parse the raw request target itself.
64	func (s *store) gateway(w http.ResponseWriter, r *http.Request) {
65		if r.Method != http.MethodGet {
66			w.Header().Set("Allow", http.MethodGet)
67			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
68			return
69		}
70		rest, ok := gatewayRawPath(r)
71		if !ok {
72			// In principle the dispatcher only routes matching targets here.
73			writeError(w, http.StatusNotFound, "object_not_found")
74			return
75		}
76		rawSegments := strings.Split(rest, "/")
77		rootCID, ok := decodeGatewaySegment(rawSegments[0])
78		if !ok || !validCID(rootCID) {
79			writeError(w, http.StatusBadRequest, "invalid_cid")
80			return
81		}
82		rawPath := rawSegments[1:]
83		if len(rawPath) > maxGatewaySegments {
84			writeError(w, http.StatusBadRequest, "invalid_path")
85			return
86		}
87		segments := make([]string, len(rawPath))
88		for i, raw := range rawPath {
89			seg, ok := decodeGatewaySegment(raw)
90			if !ok || !utf8.ValidString(seg) || seg == "" ||
91				strings.ContainsAny(seg, `/\`) || seg == "." || seg == ".." {
92				writeError(w, http.StatusBadRequest, "invalid_path")
93				return
94			}
95			segments[i] = seg
96		}
97	
98		outcome := s.resolveGateway(rootCID, segments)
99		if outcome.status != 0 {
100			writeError(w, outcome.status, outcome.code)
101			return
102		}
103		mediaType := "application/octet-stream"
104		if outcome.directory {
105			mediaType = directoryMediaType
106		}
107		w.Header().Set("Content-Type", mediaType)
108		w.Header().Set("Content-Length", strconv.Itoa(outcome.obj.size))
109		for _, chunk := range outcome.obj.chunks {
110			_, _ = w.Write(chunk)
111		}
112	}
113	
114	// gatewayOutcome is either a successful resolution (obj plus whether it is a
115	// directory) or the error code and status to report.
116	type gatewayOutcome struct {
117		obj       *object
118		directory bool
119		code      string
120		status    int
121	}
122	
123	// resolveGateway walks from the root CID through each path segment against a
124	// single consistent snapshot of the object store: the read lock is held for
125	// the whole walk, so concurrent garbage collection can never make one
126	// request observe objects from different points in time. It never initiates
127	// a remote retrieval; locally absent referenced objects fail the request.
128	func (s *store) resolveGateway(rootCID string, segments []string) gatewayOutcome {
129		s.mu.RLock()
130		defer s.mu.RUnlock()
131	
132		root, exists := s.objects[rootCID]
133		if !exists {
134			return gatewayOutcome{code: "object_not_found", status: http.StatusNotFound}
135		}
136		entries, valid := parseDirectory(root.body())
137		if !valid {
138			return gatewayOutcome{code: "invalid_directory", status: http.StatusUnprocessableEntity}
139		}
140		current := root
141		for i, name := range segments {
142			entry, found := entries[name]
143			if !found {
144				return gatewayOutcome{code: "path_not_found", status: http.StatusNotFound}
145			}
146			last := i == len(segments)-1
147			if entry.typ == "file" {
148				// Descending through a file is a path-type conflict reported from
149				// the directory metadata alone; the file object need not exist.
150				if !last {
151					return gatewayOutcome{code: "not_directory", status: http.StatusConflict}
152				}
153				target := s.objects[entry.cid]
154				if target == nil {
155					return gatewayOutcome{code: "gateway_target_missing", status: http.StatusFailedDependency}
156				}
157				return gatewayOutcome{obj: target, directory: false}
158			}
159			target := s.objects[entry.cid]
160			if target == nil {
161				return gatewayOutcome{code: "gateway_target_missing", status: http.StatusFailedDependency}
162			}
163			childEntries, valid := parseDirectory(target.body())
164			if !valid {
165				return gatewayOutcome{code: "invalid_directory", status: http.StatusUnprocessableEntity}
166			}
167			if last {
168				return gatewayOutcome{obj: target, directory: true}
169			}
170			current = target
171			entries = childEntries
172		}
173		return gatewayOutcome{obj: current, directory: true}
174	}
175	
176	// body concatenates the object's chunks back into the stored byte sequence.
177	// Object bytes are immutable once stored.
178	func (o *object) body() []byte {
179		if len(o.chunks) == 0 {
180			return []byte{}
181		}
182		if len(o.chunks) == 1 {
183			return o.chunks[0]
184		}
185		return bytes.Join(o.chunks, nil)
186	}
187	
188	// parseDirectory fully validates one directory document and returns its
189	// entries indexed by name. A directory object is strict UTF-8 JSON whose top
190	// level carries exactly version (fixed at 1) and entries (at most 4096);
191	// every entry carries exactly name, type and cid, names are unique and
192	// strictly increasing by Unicode code point, each name is one path segment
193	// of 1..255 code points without "/", "\\", "."/"..", NUL or other control
194	// characters, type is file or directory, and cid has the existing shape.
195	func parseDirectory(body []byte) (map[string]directoryEntry, bool) {
196		if !utf8.Valid(body) || !wellFormedJSON(body) {
197			return nil, false
198		}
199		var doc directoryJSON
200		dec := json.NewDecoder(bytes.NewReader(body))
201		dec.DisallowUnknownFields()
202		if err := dec.Decode(&doc); err != nil {
203			return nil, false
204		}
205		if doc.Version == nil || doc.Entries == nil || *doc.Entries == nil {
206			return nil, false
207		}
208		version, err := parseInt(*doc.Version)
209		if err != nil || version != directoryVersion {
210			return nil, false
211		}
212		raw := *doc.Entries
213		if len(raw) > maxDirectoryEntries {
214			return nil, false
215		}
216		entries := make(map[string]directoryEntry, len(raw))
217		prev := ""
218		for i := range raw {
219			e := raw[i]
220			if e.Name == nil || e.Type == nil || e.CID == nil {
221				return nil, false
222			}
223			name := *e.Name
224			if !validDirectoryName(name) || !runesLess(prev, name) {
225				return nil, false
226			}
227			if *e.Type != "file" && *e.Type != "directory" {
228				return nil, false
229			}
230			if !validCID(*e.CID) {
231				return nil, false
232			}
233			entries[name] = directoryEntry{name: name, typ: *e.Type, cid: *e.CID}
234			prev = name
235		}
236		return entries, true
237	}
238	
239	// validDirectoryName reports whether name satisfies the entry-name contract:
240	// 1..255 Unicode code points, neither "." nor "..", without "/", "\\", NUL
241	// or any Cc control character.
242	func validDirectoryName(name string) bool {
243		n := utf8.RuneCountInString(name)
244		if n < 1 || n > maxNameRunes || name == "." || name == ".." {
245			return false
246		}
247		if strings.ContainsAny(name, `/\`) {
248			return false
249		}
250		for _, r := range name {
251			if r < 0x20 || r == 0x7f || (r >= 0x80 && r <= 0x9f) {
252				return false
253			}
254		}
255		return true
256	}
257	
258	// runesLess reports whether a sorts strictly before b by Unicode code point.
259	// UTF-8 preserves code-point order byte-wise, but the comparison is done on
260	// runes to state the contract directly. Inputs are already valid UTF-8.
261	func runesLess(a, b string) bool {
262		for a != "" && b != "" {
263			ra, sizeA := utf8.DecodeRuneInString(a)
264			rb, sizeB := utf8.DecodeRuneInString(b)
265			if ra != rb {
266				return ra < rb
267			}
268			a = a[sizeA:]
269			b = b[sizeB:]
270		}
271		return a == "" && b != ""
272	}
273	
274	// decodeGatewaySegment percent-decodes exactly one raw path segment, exactly
275	// once: every "%" must be followed by two hex digits, "+" is literal and
276	// there is no recursive decoding. The caller is responsible for the UTF-8
277	// and character checks on the result.
278	func decodeGatewaySegment(seg string) (string, bool) {
279		if !strings.ContainsRune(seg, '%') {
280			return seg, true
281		}
282		var b strings.Builder
283		b.Grow(len(seg))
284		for i := 0; i < len(seg); i++ {
285			c := seg[i]
286			if c != '%' {
287				b.WriteByte(c)
288				continue
289			}
290			if i+2 >= len(seg) {
291				return "", false
292			}
293			hi, okHi := hexValue(seg[i+1])
294			lo, okLo := hexValue(seg[i+2])
295			if !okHi || !okLo {
296				return "", false
297			}
298			b.WriteByte(hi<<4 | lo)
299			i += 2
300		}
301		return b.String(), true
302	}
303	
304	// hexValue converts one hexadecimal digit to its value.
305	func hexValue(c byte) (byte, bool) {
306		switch {
307		case c >= '0' && c <= '9':
308			return c - '0', true
309		case c >= 'a' && c <= 'f':
310			return c - 'a' + 10, true
311		case c >= 'A' && c <= 'F':
312			return c - 'A' + 10, true
313		}
314		return 0, false
315	}
316	
317	// gatewayRawPath returns the percent-encoded request-target path after
318	// gatewayPrefix. The raw target is used so escaped slashes and dots are
319	// preserved exactly as sent; ServeMux never sees gateway requests.
320	func gatewayRawPath(r *http.Request) (string, bool) {
321		target := r.RequestURI
322		if target == "" {
323			target = r.URL.EscapedPath()
324		}
325		if i := strings.IndexByte(target, '?'); i >= 0 {
326			target = target[:i]
327		}
328		if !strings.HasPrefix(target, gatewayPrefix) {
329			return "", false
330		}
331		return target[len(gatewayPrefix):], true
332	}
