package server

import (
	"encoding/json"
	"io"
	"mime"
	"net/http"
	"strconv"
)

// objectResponse is the JSON body returned by POST /v1/objects.
type objectResponse struct {
	CID       string   `json:"cid"`
	Size      int      `json:"size"`
	ChunkSize int      `json:"chunkSize"`
	Chunks    []string `json:"chunks"`
	Created   bool     `json:"created"`
}

// manifestResponse is the JSON body of GET /v1/objects/{cid}/manifest.
type manifestResponse struct {
	CID       string   `json:"cid"`
	Size      int      `json:"size"`
	ChunkSize int      `json:"chunkSize"`
	Chunks    []string `json:"chunks"`
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func writeError(w http.ResponseWriter, status int, code string) {
	writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
}

// postObject handles POST /v1/objects.
func (s *store) postObject(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/octet-stream" {
		writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, MaxObjectSize+1))
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if len(body) > MaxObjectSize {
		writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
		return
	}

	obj := newObject(body)
	stored, created := s.put(obj, auditObjectUpload, nil)
	status := http.StatusOK
	if created {
		status = http.StatusCreated
	}
	writeJSON(w, status, objectResponse{
		CID:       stored.cid,
		Size:      stored.size,
		ChunkSize: ChunkSize,
		Chunks:    stored.cids,
		Created:   created,
	})
}

// newObject splits a body into chunks under the fixed rules and derives its
// root identifier from the resulting manifest.
func newObject(body []byte) *object {
	obj := &object{size: len(body), chunks: [][]byte{}, cids: []string{}}
	for start := 0; start < len(body); start += ChunkSize {
		end := start + ChunkSize
		if end > len(body) {
			end = len(body)
		}
		chunk := body[start:end]
		obj.chunks = append(obj.chunks, chunk)
		obj.cids = append(obj.cids, chunkCID(chunk))
	}
	obj.cid = rootCID(obj.size, obj.cids)
	return obj
}

// lookupObject validates the path identifier and resolves the object,
// writing the appropriate error response on failure.
func (s *store) lookupObject(w http.ResponseWriter, r *http.Request) *object {
	cid := r.PathValue("cid")
	if !validCID(cid) {
		writeError(w, http.StatusBadRequest, "invalid_cid")
		return nil
	}
	obj := s.get(cid)
	if obj == nil {
		writeError(w, http.StatusNotFound, "object_not_found")
		return nil
	}
	return obj
}

// getObject handles GET /v1/objects/{cid}.
func (s *store) getObject(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	obj := s.lookupObject(w, r)
	if obj == nil {
		return
	}
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Length", strconv.Itoa(obj.size))
	for _, chunk := range obj.chunks {
		_, _ = w.Write(chunk)
	}
}

// getManifest handles GET /v1/objects/{cid}/manifest.
func (s *store) getManifest(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	obj := s.lookupObject(w, r)
	if obj == nil {
		return
	}
	writeJSON(w, http.StatusOK, manifestResponse{
		CID:       obj.cid,
		Size:      obj.size,
		ChunkSize: ChunkSize,
		Chunks:    obj.cids,
	})
}

package server

import (
	"net/http"
	"strconv"
)

// statsResponse is the JSON body of GET /v1/storage/stats. Objects counts
// every live object (empty ones included); logicalBytes sums their body
// sizes. Blocks counts the unique blocks referenced by live objects and
// storedBytes sums their raw lengths, each shared block counted once.
type statsResponse struct {
	Objects      int `json:"objects"`
	LogicalBytes int `json:"logicalBytes"`
	Blocks       int `json:"blocks"`
	StoredBytes  int `json:"storedBytes"`
}

// getBlock handles GET /v1/blocks/{cid}.
func (s *store) getBlockByID(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	cid := r.PathValue("cid")
	if !validCID(cid) {
		writeError(w, http.StatusBadRequest, "invalid_cid")
		return
	}
	data := s.getBlock(cid)
	if data == nil {
		writeError(w, http.StatusNotFound, "block_not_found")
		return
	}
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Length", strconv.Itoa(len(data)))
	_, _ = w.Write(data)
}

// getStorageStats handles GET /v1/storage/stats.
func (s *store) getStorageStats(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", http.MethodGet)
		writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	st := s.stats()
	writeJSON(w, http.StatusOK, statsResponse{
		Objects:      st.objects,
		LogicalBytes: st.logicalBytes,
		Blocks:       st.blocks,
		StoredBytes:  st.storedBytes,
	})
}

// Package server exposes the frozen public surface of CidVault.
//
// The baseline only reports process health. Later work adds the capabilities
// described in README.md; keep the exported surface here backward compatible.
package server

import (
	"encoding/json"
	"net/http"
	"strings"
)

// Version is the baseline release identifier.
const Version = "0.1.0"

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// Handler returns the HTTP surface served by the baseline.
func Handler() http.Handler {
	audit := newAuditLog()
	objects := newStore()
	objects.audit = audit
	sealed := newSealedStore()
	providers := newProviderDirectory()
	providers.audit = audit
	retriever := newRetriever(objects, providers)
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "cidvault", Version: Version})
	})
	mux.HandleFunc("/v1/objects", objects.postObject)
	mux.HandleFunc("/v1/sealed-objects", sealed.postSealedObject)
	mux.HandleFunc("/v1/sealed-objects/{cid}", sealed.sealedObjectByID)
	mux.HandleFunc("/v1/sealed-objects/{cid}/envelope", sealed.getSealedEnvelope)
	mux.HandleFunc("/v1/objects/{cid}", objects.getObject)
	mux.HandleFunc("/v1/objects/{cid}/manifest", objects.getManifest)
	mux.HandleFunc("/v1/objects/{cid}/metadata", objects.metadataByID)
	mux.HandleFunc("/v1/blocks/{cid}", objects.getBlockByID)
	mux.HandleFunc("/v1/bundles", objects.postBundle)
	mux.HandleFunc("/v1/bundles/{cid}", objects.getBundle)
	mux.HandleFunc("/v1/delta-bundles", objects.postDeltaBundle)
	mux.HandleFunc("/v1/delta-bundles/{cid}", objects.postDeltaBundleByID)
	mux.HandleFunc("/v1/storage/stats", objects.getStorageStats)
	mux.HandleFunc("/v1/pins", objects.getPins)
	mux.HandleFunc("/v1/pins/{cid}", objects.pinByID)
	mux.HandleFunc("/v1/gc", objects.gc)
	mux.HandleFunc("/v1/providers/{cid}", providers.providersByCID)
	mux.HandleFunc("/v1/providers/{cid}/{providerId}", providers.providerByID)
	mux.HandleFunc("/v1/retrievals/{cid}", retriever.postRetrieval)
	mux.HandleFunc("/v1/retrievability-proofs/{cid}", objects.postRetrievabilityProof)
	mux.HandleFunc("/v1/audit/events", audit.getEvents)

	// The gateway is dispatched before ServeMux on the raw request target:
	// ServeMux cleans "."/".." and empty segments with redirects and hands
	// handlers already-percent-decoded path values, both of which would
	// violate the gateway's exact single-decoding path contract. The named
	// reference routes use the same raw dispatch so each name is decoded
	// exactly once and an encoded slash cannot be rewritten into another
	// route.
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch {
		case hasGatewayPrefix(r):
			objects.gateway(w, r)
		case hasRefsPrefix(r):
			objects.refsDispatch(w, r)
		default:
			mux.ServeHTTP(w, r)
		}
	})
}

// hasGatewayPrefix reports whether the request target names a gateway route.
// The raw target is inspected (query stripped) so percent-encoded slashes and
// dots survive untouched.
func hasGatewayPrefix(r *http.Request) bool {
	target := r.RequestURI
	if target == "" {
		target = r.URL.EscapedPath()
	}
	if i := strings.IndexByte(target, '?'); i >= 0 {
		target = target[:i]
	}
	return strings.HasPrefix(target, gatewayPrefix)
}

// hasRefsPrefix reports whether the request target names a named-reference
// route. As with the gateway, the raw target is inspected so the name is
// percent-decoded exactly once by the dispatcher.
func hasRefsPrefix(r *http.Request) bool {
	target := r.RequestURI
	if target == "" {
		target = r.URL.EscapedPath()
	}
	if i := strings.IndexByte(target, '?'); i >= 0 {
		target = target[:i]
	}
	return strings.HasPrefix(target, refsPrefix)
}

